    "/*\n"
    " * $Revisio" "n: $\n"
    " * $Lo" "g: $\n"
    " *\n"
    " * CHECK THIS FILE IN WITH `-ko`.\n"
    " *\n"
    " * Not for the usual reason (a keyword inside a string literal -- the\n"
    " * generators defang those now).  This file's text is copied VERBATIM into\n"
    " * gpu_u32_walker.cl and metal_u32_walker.metal, and from there into the\n"
    " * _str.h that the JIT compiles.  An expanded $Lo" "g$ would therefore grow the\n"
    " * KERNEL SOURCE by the whole revision history on every check-in -- changing\n"
    " * the kernel-cache key each time and re-JITting for nothing.  The other .cl\n"
    " * files in this directory are -ko for the same reason: gpu_md5_rules.cl is at\n"
    " * revision 1.34 and its working copy still reads `$Lo" "g: $`.\n"
    " */\n"
    "/* gpu_u32_walker.inc -- the UTF-32 rule walker, shared body.\n"
    " *\n"
    " * THIS FILE IS NOT COMPILED DIRECTLY.  gen_u32_walker.py emits\n"
    " * gpu_md5_rules32.cl (OpenCL) and metal_md5_rules32.metal (Metal) from it,\n"
    " * substituting only the address-space spellings.  That is deliberate: the\n"
    " * byte walker exists as two hand-maintained 1100-line twins\n"
    " * (gpu_md5_rules.cl / metal_md5_rules.metal) and keeping them in step is a\n"
    " * standing cost.  One source removes the question for this walker, and it is\n"
    " * the concrete answer to \"keep OpenCL and Metal at feature parity\".\n"
    " *\n"
    " * The CPU reference is applyrule32() in ../ruleproc32.c and it is the ONLY\n"
    " * authority.  Every arm below cites the behaviour it mirrors where that\n"
    " * behaviour is surprising; where it is not, the arm is a transliteration and\n"
    " * is deliberately unclever.\n"
    " *\n"
    " * ---- WHAT THIS WALKER IS NOT -------------------------------------------\n"
    " *\n"
    " * 1. It does NOT implement the twelve RULE32_OP_*_STR string-operand opcodes\n"
    " *    (0x1002..0x100C).  MEASURED reason, not a preference: across 338,310\n"
    " *    real rule lines (HashMob.100k.rule, all_gj.rule, game.rule) exactly FOUR\n"
    " *    use one.  They appear only in hand-authored UTF-32 rules.  Excluding\n"
    " *    them removes every variable-length operand from the device stream except\n"
    " *    the two collapsed affix runs, which keeps the operand skip a constant.\n"
    " *    A rule using one is marked \"no UTF-32 form\" host-side and its pairs are\n"
    " *    walked on the CPU, so correctness is preserved by construction.\n"
    " *\n"
    " * 2. It computes VARIANT 0 ONLY.  applyrule32 can have two right answers for\n"
    " *    one (word, rule) when a Turkish/Azeri dotted-i mapping is reached, but\n"
    " *    mdxfind's CPU -8 path calls applyrule_u32(..., variant 0, &nvar) and only\n"
    " *    COUNTS the cases where nvar > 1 (Variants_dropped).  Matching that is\n"
    " *    what makes GPU == CPU reachable at all; emitting both variants here\n"
    " *    would diverge from the oracle on every word containing i or I under\n"
    " *    l / u / c / C / t.\n"
    " *\n"
    " * 3. Buffer exhaustion is DEFINED behaviour, not an error, exactly as in the\n"
    " *    byte walker: the rule does what it can, stops, and whatever was\n"
    " *    generated becomes the candidate.  The CPU engine's bound is\n"
    " *    RULE32_MAXCP (200K codepoints) and this one's is U32_BUF_LIMIT, so GPU\n"
    " *    and CPU candidates diverge above U32_BUF_LIMIT.  `-G none` is the answer\n"
    " *    when CPU-exact output is required at that length.\n"
    " */\n"
    "\n"
    "/* ---- THE TWO BUFFER ADDRESS SPACES, and why they are not one ----------\n"
    " *\n"
    " * U32_BUF     the WORKING buffers: the staged codepoints, the memory-verb\n"
    " *             scratch, and the encode target.  Two arrays of U32_BUF_ELEMS\n"
    " *             uints plus a byte buffer -- about 24 KB per lane.\n"
    " * U32_SCRATCH the 3-element array u32_upper_full writes an expanded uppercase\n"
    " *             into.  Twelve bytes, always lane-local.\n"
    " *\n"
    " * On OpenCL both expand to nothing: private is the default and drivers spill\n"
    " * to global transparently.  On METAL THEY MUST DIFFER, and the reason is on\n"
    " * the record in this tree rather than theoretical -- task #250 moved the byte\n"
    " * walker's `buf` out of `thread` because on an M2 Max the PSO-create gate\n"
    " * rejected it outright with \"Compute function exceeds available temporary\n"
    " * registers\".  Apple Metal does NOT spill.  24 KB of `thread` arrays would\n"
    " * fail the same way, so U32_BUF is `device` there and the host provides the\n"
    " * slice, exactly as buf_scratch_pool already does for the byte walker.\n"
    " *\n"
    " * U32_SCRATCH stays `thread` because its callers pass a plain local array, and\n"
    " * Metal type-checks address spaces: a `device`-qualified parameter cannot\n"
    " * accept a thread-local argument.  Collapsing the two into one macro compiles\n"
    " * on OpenCL and fails on Metal, which is exactly the kind of difference that\n"
    " * only shows up on the backend you were not testing. */\n"
    "\n"
    "/* ==== sizing ==========================================================\n"
    " *\n"
    " * ELEMENTS, not bytes.  One element is a uint32_t codepoint here, where the\n"
    " * byte walker's element is a uchar -- so the same element count costs 4x the\n"
    " * memory.  That is the headline occupancy risk of this walker and the reason\n"
    " * U32_BUF_ELEMS is injectable separately from RULE_BUF_MAX: a 2026 attempt at\n"
    " * a second 40960-BYTE buffer already FATAL'd CL_OUT_OF_HOST_MEMORY on an\n"
    " * RTX 3080 (see gpu_md5_rules.cl, the apply_rule scratch comment), and this\n"
    " * walker needs two buffers of uint.\n"
    " *\n"
    " * U32_BUF_LIMIT is 15 below the allocation, matching the byte walker: it\n"
    " * covers the n+1 boundary reads in the per-op bounds checks.\n"
    " */\n"
    "/* DEFAULT 2048 ELEMENTS, chosen for correctness parity with the byte walker,\n"
    " * not for memory.  The input-word gate is GPU_RULES_MAX_INPUT_LEN = 1024\n"
    " * BYTES (gpujob.h), a 1024-byte UTF-8 word is at most 1024 codepoints, and\n"
    " * the byte walker's RULE_BUF_MAX is 2 x its gate so that a `d` or `f` on a\n"
    " * full-length word still fits.  1024 elements here would stage the widest\n"
    " * allowed input with NO growth headroom and would turn every duplication verb\n"
    " * on a long word into a defined-behaviour divergence from the CPU.\n"
    " *\n"
    " * The cost is stated rather than hidden.  Per-thread private memory, MEASURED\n"
    " * from the declarations in gpu_md5_rules32.cl:\n"
    " *\n"
    " *   byte walker      buf 2048 uchar + mem 2048 uchar            =  4,096 B\n"
    " *   pure UTF-32      u32buf+u32mem 2048 uint + cand 8192 uchar  = 24,576 B  6.0x\n"
    " *   mixed            the above + bytebuf 2048 uchar             = 26,624 B  6.5x\n"
    " *\n"
    " * That is the headline occupancy risk of this walker and the reason the knob\n"
    " * exists: a 2026 attempt at a second 40960-BYTE buffer already FATAL'd\n"
    " * CL_OUT_OF_HOST_MEMORY on an RTX 3080.  Lowering it to 1024 halves the two\n"
    " * uint buffers and quarters `cand`, at the price of divergence above\n"
    " * U32_BUF_LIMIT -- which is DEFINED behaviour, not an error.  Both settings\n"
    " * are in the trial matrix. */\n"
    "/* Presence marker.  Kernel sources compiled into the SAME translation unit as\n"
    " * this walker test `#ifdef GPU_U32_WALKER_PRESENT` to decide whether they have\n"
    " * a UTF-32 arm at all.  It exists so one kernel source (gpu_template.cl,\n"
    " * metal_template.metal, the kernel-A pair) serves both engines: the host\n"
    " * appends this walker to the source list only when `-8` is active, so a\n"
    " * byte-mode run compiles text that is byte-identical to the pre-UTF-32\n"
    " * program -- same cache key, same private-memory footprint, same PTX/AIR.\n"
    " * A `-DGPU_U32_RULES` build option would have done the same job, but it would\n"
    " * have had to be threaded through 57 separate per-algorithm compile helpers\n"
    " * and could drift out of step with the source list it describes; this cannot,\n"
    " * because it IS the source list. */\n"
    "#define GPU_U32_WALKER_PRESENT 1\n"
    "\n"
    "#ifndef U32_BUF_ELEMS\n"
    "#define U32_BUF_ELEMS  2048\n"
    "#endif\n"
    "#ifndef U32_BUF_LIMIT\n"
    "#define U32_BUF_LIMIT  (U32_BUF_ELEMS - 15)\n"
    "#endif\n"
    "\n"
    "/* Bytes of device-side working memory ONE lane needs, laid out as\n"
    " *   [0                 .. U32_BUF_ELEMS*4)    u32buf  codepoints\n"
    " *   [U32_BUF_ELEMS*4   .. U32_BUF_ELEMS*8)    u32mem  memory verbs\n"
    " *   [U32_BUF_ELEMS*8   .. + U32_OUT_BYTES)    the candidate bytes\n"
    " *\n"
    " * Defined HERE, in the shared body, because the HOST has to allocate exactly\n"
    " * this and the kernel has to carve exactly this -- two places that must agree\n"
    " * to the byte, so they read it from one constant.  A multiple of 16, so every\n"
    " * region is aligned for the uint casts on both backends.\n"
    " *\n"
    " * At U32_BUF_ELEMS = 2048 that is 24,576 bytes per lane, and the grid is one\n"
    " * lane per WORD, so ~402 MB at the 16,384-word peak.  Sized deliberately:\n"
    " * against the 40 KB-per-lane the pre-task-#250 byte walker wanted at the same\n"
    " * peak it is a fraction, and Apple Silicon has 8-24 GB of unified memory. */\n"
    "#define U32_OUT_BYTES   (4 * U32_BUF_ELEMS)\n"
    "#define U32_SLOT_BYTES  (U32_BUF_ELEMS * 8 + U32_OUT_BYTES)\n"
    "\n"
    "/* Return codes, in applyrule32()'s numbering (ruleproc32.h).  NOT the byte\n"
    " * walker's: the two engines number their negatives INVERSELY and collapsing\n"
    " * them is a documented trap (mdxfind.c, the applyrule_u32 contract table).\n"
    " * The kernel bodies translate. */\n"
    "#define U32_ERR_INVALID (-1)   /* input is not well-formed UTF-8: pair dies  */\n"
    "#define U32_ERR_NOROOM  (-2)   /* buffer too small: caller sized it wrongly  */\n"
    "#define U32_REJECTED    (-3)   /* a rejection rule fired: emit nothing       */\n"
    "\n"
    "#define U32_END          0u    /* terminates a packed rule (RULE32_END)      */\n"
    "\n"
    "/* Opcodes for the collapsed affix runs.  Values from ruleproc32.h; they sit\n"
    " * above the byte engine's 0xc0..0xfd range on purpose. */\n"
    "#define RULE32_OP_APPEND_MULTI   0x1000u\n"
    "#define RULE32_OP_PREPEND_MULTI  0x1001u\n"
    "\n"
    "/* Named codepoints, from ruleproc32.c. */\n"
    "#define U32_ZWJ          0x200Du\n"
    "#define U32_ZWNJ         0x200Cu\n"
    "#define U32_EMOJI_MOD_LO 0x1F3FBu\n"
    "#define U32_EMOJI_MOD_HI 0x1F3FFu\n"
    "#define U32_RI_LO        0x1F1E6u\n"
    "#define U32_RI_HI        0x1F1FFu\n"
    "#define U32_TAG_LO       0xE0020u\n"
    "#define U32_TAG_HI       0xE007Fu\n"
    "#define U32_HW_VOICED     0xFF9Eu\n"
    "#define U32_HW_SEMIVOICED 0xFF9Fu\n"
    "#define U32_SMALL_I       0x0069u\n"
    "#define U32_CAPITAL_I     0x0049u\n"
    "/* The Turkish/Azeri dotted-i family.  ruleproc32.c names these\n"
    " * CP_LATIN_CAPITAL_I_DOT / CP_LATIN_SMALL_DOTLESS; same values, and the\n"
    " * special cases in u32_upper/u32_lower below are its cp_upper/cp_lower\n"
    " * token for token. */\n"
    "#define U32_CAPITAL_I_DOT 0x0130u\n"
    "#define U32_SMALL_DOTLESS 0x0131u\n"
    "#define U32_SMALL_SIGMA   0x03C3u\n"
    "#define U32_FINAL_SIGMA   0x03C2u\n"
    "\n"
    "/* `=NX` and `%NX` pack as their LITERAL ASCII bytes, a historical exception\n"
    " * to the high-bit opcode range.  gpu_common.cl already names them for the\n"
    " * byte walker; ../rule_ops.h does not, so the host twin test needs them from\n"
    " * here.  Guarded so whichever source arrives first wins. */\n"
    "#ifndef RULE_OP_REJ_AT_CHR\n"
    "#define RULE_OP_REJ_AT_CHR   0x3du\n"
    "#endif\n"
    "#ifndef RULE_OP_REJ_CNT_CHR\n"
    "#define RULE_OP_REJ_CNT_CHR  0x25u\n"
    "#endif\n"
    "\n"
    "#define U32_ENCODABLE(cp) ((cp) <= 0x10FFFFu && ((cp) < 0xD800u || (cp) > 0xDFFFu))\n"
    "\n"
    "\n"
    "/* ==== UTF-8 -> UTF-32, strict =========================================\n"
    " *\n"
    " * Mirrors utf8_to_utf32() (ruleproc32.c).  STRICT is the whole point: a\n"
    " * permissive decoder accepts overlongs and CESU-8 surrogates silently and the\n"
    " * failure then shows up much later as a candidate that never matches.\n"
    " * Rejected here, as there: overlong forms, surrogates encoded as three bytes,\n"
    " * scalars above U+10FFFF, lead bytes 0xC0/0xC1/0xF5..0xFF, truncated\n"
    " * sequences and stray continuation bytes.\n"
    " *\n"
    " * Returns the codepoint count, or U32_ERR_INVALID / U32_ERR_NOROOM.\n"
    " *\n"
    " * The ASCII fast path is first and is not an optimisation of the decoder so\n"
    " * much as of the DIVERGENCE: a warp of ASCII words takes the one-byte arm\n"
    " * uniformly and never enters the length dispatch below.\n"
    " */\n"
    "U32_SI int u32_decode(U32_GLOBAL const uchar *in, int inlen,\n"
    "                      U32_BUF uint *out, int outmax)\n"
    "{\n"
    "    int i = 0, n = 0;\n"
    "\n"
    "    while (i < inlen) {\n"
    "        uint b0 = (uint)in[i];\n"
    "        uint cp;\n"
    "        int need;\n"
    "\n"
    "        if (n >= outmax) return U32_ERR_NOROOM;\n"
    "\n"
    "        if (b0 < 0x80u) { out[n++] = b0; i++; continue; }\n"
    "\n"
    "        if (b0 < 0xC2u) return U32_ERR_INVALID;   /* continuation, C0, C1 */\n"
    "        else if (b0 < 0xE0u) { cp = b0 & 0x1Fu; need = 1; }\n"
    "        else if (b0 < 0xF0u) { cp = b0 & 0x0Fu; need = 2; }\n"
    "        else if (b0 < 0xF5u) { cp = b0 & 0x07u; need = 3; }\n"
    "        else return U32_ERR_INVALID;              /* F5..FF never valid */\n"
    "\n"
    "        /* The continuation bytes live at i+1 .. i+need, so the sequence is\n"
    "         * truncated unless i+need is still inside the buffer. */\n"
    "        if (i + need >= inlen) return U32_ERR_INVALID;\n"
    "        for (int k = 1; k <= need; k++) {\n"
    "            uint bc = (uint)in[i + k];\n"
    "            if ((bc & 0xC0u) != 0x80u) return U32_ERR_INVALID;\n"
    "            cp = (cp << 6) | (bc & 0x3Fu);\n"
    "        }\n"
    "        /* Overlong, surrogate and out-of-range checks, per length. */\n"
    "        if (need == 1) { if (cp < 0x80u)    return U32_ERR_INVALID; }\n"
    "        else if (need == 2) {\n"
    "            if (cp < 0x800u)                return U32_ERR_INVALID;\n"
    "            if (cp >= 0xD800u && cp <= 0xDFFFu) return U32_ERR_INVALID;\n"
    "        } else {\n"
    "            if (cp < 0x10000u || cp > 0x10FFFFu) return U32_ERR_INVALID;\n"
    "        }\n"
    "        out[n++] = cp;\n"
    "        i += need + 1;\n"
    "    }\n"
    "    return n;\n"
    "}\n"
    "\n"
    "/* ==== UTF-32 -> UTF-8 =================================================\n"
    " *\n"
    " * Mirrors utf32_to_utf8() (ruleproc32.c), INCLUDING the drop rule: there is\n"
    " * no \"invalid\" outcome here.  An unencodable codepoint is DROPPED and the\n"
    " * rest of the line is emitted.  The only way to get one is a verb doing\n"
    " * arithmetic on a codepoint -- + - L R and s -- pushing it past U+10FFFF or\n"
    " * into the surrogate block.  Keeping that test in the ENCODER rather than in\n"
    " * those four arms is what keeps the walker free of range checks.\n"
    " *\n"
    " * Returns the byte count, or U32_ERR_NOROOM.\n"
    " */\n"
    "U32_SI int u32_encode(U32_BUF const uint *in, int inlen,\n"
    "                      U32_BUF uchar *out, int outmax)\n"
    "{\n"
    "    int i, n = 0;\n"
    "\n"
    "    for (i = 0; i < inlen; i++) {\n"
    "        uint cp = in[i];\n"
    "\n"
    "        if (!U32_ENCODABLE(cp)) continue;         /* dropped, line survives */\n"
    "\n"
    "        if (cp < 0x80u) {\n"
    "            if (n + 1 > outmax) return U32_ERR_NOROOM;\n"
    "            out[n++] = (uchar)cp;\n"
    "        } else if (cp < 0x800u) {\n"
    "            if (n + 2 > outmax) return U32_ERR_NOROOM;\n"
    "            out[n++] = (uchar)(0xC0u | (cp >> 6));\n"
    "            out[n++] = (uchar)(0x80u | (cp & 0x3Fu));\n"
    "        } else if (cp < 0x10000u) {\n"
    "            if (n + 3 > outmax) return U32_ERR_NOROOM;\n"
    "            out[n++] = (uchar)(0xE0u | (cp >> 12));\n"
    "            out[n++] = (uchar)(0x80u | ((cp >> 6) & 0x3Fu));\n"
    "            out[n++] = (uchar)(0x80u | (cp & 0x3Fu));\n"
    "        } else {\n"
    "            if (n + 4 > outmax) return U32_ERR_NOROOM;\n"
    "            out[n++] = (uchar)(0xF0u | (cp >> 18));\n"
    "            out[n++] = (uchar)(0x80u | ((cp >> 12) & 0x3Fu));\n"
    "            out[n++] = (uchar)(0x80u | ((cp >> 6) & 0x3Fu));\n"
    "            out[n++] = (uchar)(0x80u | (cp & 0x3Fu));\n"
    "        }\n"
    "    }\n"
    "    return n;\n"
    "}\n"
    "\n"
    "/* ==== cluster layer ===================================================\n"
    " *\n"
    " * Every position and length operand in this engine counts GRAPHEME CLUSTERS.\n"
    " * A rule that says \"delete character 3\" means the third thing a reader sees,\n"
    " * and on vocalised Arabic or pointed Hebrew the third codepoint is routinely\n"
    " * a vowel mark hanging off the second letter.\n"
    " *\n"
    " * MEASURED, and it decided the design: classifying every verb by whether its\n"
    " * applyrule32 arm calls cl_count / cl_start / cl_next shows that a\n"
    " * CLUSTER-FREE subset covers only 34.22% of HashMob.100k.rule, 25.69% of\n"
    " * HashMob.10k.rule, 26.40% of all_gj.rule and 4.22% of game.rule -- because\n"
    " * the excluded verbs are the COMMON ones (i 63619, o 26646, T 15685,\n"
    " * r 15293, ' 13399, ] 13039, * 8732, { 8708 occurrences in HashMob.100k).\n"
    " * So the cluster layer is implemented in full rather than avoided, and the\n"
    " * staging is by cl_all_plain instead, exactly as the CPU stages it.\n"
    " */\n"
    "\n"
    "U32_SI int u32_is_mark(uint c)\n"
    "{\n"
    "    int lo = 0, hi = U32_MARK_N - 1;\n"
    "\n"
    "    if (c < U32_MARK_LO || c > U32_MARK_HI) return 0;   /* all ASCII, 1 test */\n"
    "    while (lo <= hi) {\n"
    "        int mid = (lo + hi) >> 1;\n"
    "        if (c < u32_marks[2 * mid])      hi = mid - 1;\n"
    "        else if (c > u32_marks[2 * mid + 1]) lo = mid + 1;\n"
    "        else return 1;\n"
    "    }\n"
    "    return 0;\n"
    "}\n"
    "\n"
    "U32_SI int u32_is_ri(uint c) { return c >= U32_RI_LO && c <= U32_RI_HI; }\n"
    "\n"
    "/* UAX #29 GB6-GB8.  A Korean syllable can be written as one precomposed\n"
    " * codepoint or as conjoining jamo; macOS stores filenames decomposed, so\n"
    " * harvested Korean arrives either way. */\n"
    "U32_SI int u32_hangul_class(uint c)\n"
    "{\n"
    "    if (c >= 0x1100u && c <= 0x115Fu) return 1;   /* L */\n"
    "    if (c >= 0x1160u && c <= 0x11A7u) return 2;   /* V */\n"
    "    if (c >= 0x11A8u && c <= 0x11FFu) return 3;   /* T */\n"
    "    if (c >= 0xA960u && c <= 0xA97Cu) return 1;\n"
    "    if (c >= 0xD7B0u && c <= 0xD7C6u) return 2;\n"
    "    if (c >= 0xD7CBu && c <= 0xD7FBu) return 3;\n"
    "    if (c >= 0xAC00u && c <= 0xD7A3u)\n"
    "        return ((c - 0xAC00u) % 28u) ? 5 : 4;     /* LVT : LV */\n"
    "    return 0;\n"
    "}\n"
    "\n"
    "U32_SI int u32_hangul_join(int a, int b)\n"
    "{\n"
    "    if (a == 1) return b == 1 || b == 2 || b == 4 || b == 5;\n"
    "    if (a == 4 || a == 2) return b == 2 || b == 3;\n"
    "    if (a == 5 || a == 3) return b == 3;\n"
    "    return 0;\n"
    "}\n"
    "\n"
    "U32_SI int u32_is_extend(uint c)\n"
    "{\n"
    "    if (c >= U32_EMOJI_MOD_LO && c <= U32_EMOJI_MOD_HI) return 1;\n"
    "    if (c >= U32_TAG_LO && c <= U32_TAG_HI) return 1;\n"
    "    if (c == U32_ZWNJ) return 1;\n"
    "    if (c == U32_HW_VOICED || c == U32_HW_SEMIVOICED) return 1;\n"
    "    return u32_is_mark(c);\n"
    "}\n"
    "\n"
    "/* GB9c.  The consonant test is approximated as \"a letter of the same script\",\n"
    " * which over-joins only where a virama is followed by an independent vowel --\n"
    " * rare, and far less wrong than a dangling halant. */\n"
    "U32_SI int u32_indic_script(uint c)\n"
    "{\n"
    "    if (c >= 0x0900u && c <= 0x097Fu) return 1;\n"
    "    if (c >= 0x0980u && c <= 0x09FFu) return 2;\n"
    "    if (c >= 0x0A80u && c <= 0x0AFFu) return 3;\n"
    "    if (c >= 0x0B00u && c <= 0x0B7Fu) return 4;\n"
    "    if (c >= 0x0C00u && c <= 0x0C7Fu) return 5;\n"
    "    if (c >= 0x0D00u && c <= 0x0D7Fu) return 6;\n"
    "    if (c >= 0x1780u && c <= 0x17FFu) return 7;\n"
    "    return 0;\n"
    "}\n"
    "\n"
    "U32_SI int u32_is_linker(uint c)\n"
    "{\n"
    "    return c == 0x094Du || c == 0x09CDu || c == 0x0ACDu ||\n"
    "           c == 0x0B4Du || c == 0x0C4Du || c == 0x0D4Du ||\n"
    "           c == 0x17D2u;\n"
    "}\n"
    "\n"
    "/* Advance from i past exactly ONE cluster.  Every other cluster routine is\n"
    " * written in terms of this, so the definition lives in one place. */\n"
    "U32_SI int u32_cl_next(U32_BUF const uint *b, int n, int i)\n"
    "{\n"
    "    if (i >= n) return n;\n"
    "\n"
    "    /* Fast path, and it carries almost all real traffic.  Nothing below the\n"
    "     * lowest mark at U+0300 can continue a cluster and nothing below U+1F1E6\n"
    "     * is a regional indicator, so a base under that with a successor under\n"
    "     * the mark floor is a one-codepoint cluster, settled in two compares. */\n"
    "    if (b[i] < U32_RI_LO && (i + 1 >= n || b[i + 1] < U32_MARK_LO)) return i + 1;\n"
    "\n"
    "    if (u32_is_ri(b[i])) {\n"
    "        i++;\n"
    "        if (i < n && u32_is_ri(b[i])) i++;        /* the pair is one flag */\n"
    "    } else {\n"
    "        int h = u32_hangul_class(b[i]);\n"
    "        i++;\n"
    "        if (h) {\n"
    "            while (i < n) {\n"
    "                int h2 = u32_hangul_class(b[i]);\n"
    "                if (!h2 || !u32_hangul_join(h, h2)) break;\n"
    "                h = h2; i++;\n"
    "            }\n"
    "        }\n"
    "    }\n"
    "    for (;;) {\n"
    "        int linker = 0;\n"
    "        while (i < n && u32_is_extend(b[i])) {\n"
    "            if (u32_is_linker(b[i])) linker = 1;\n"
    "            i++;\n"
    "        }\n"
    "        if (linker && i < n && u32_indic_script(b[i])) { i++; continue; }\n"
    "        if (i < n && b[i] == U32_ZWJ) {\n"
    "            i++;\n"
    "            if (i < n) i++;\n"
    "            continue;\n"
    "        }\n"
    "        break;\n"
    "    }\n"
    "    return i;\n"
    "}\n"
    "\n"
    "/* True when nothing in the buffer can join or extend, so cluster index and\n"
    " * codepoint index are the same.  ONE comparison per codepoint answers it.\n"
    " *\n"
    " * This is the staging gate.  MEASURED hit rate: 100.00% of the decodable\n"
    " * lines of NONUTF8test1.txt, 89.60% of UTF8test1.txt (overstated -- $HEX[]\n"
    " * was not unwrapped by the measuring tool), and 24.97% of UTF8test2.txt,\n"
    " * which is the honest figure for genuinely multi-script input.  So it is a\n"
    " * real optimisation and NOT a way to avoid implementing the walk.\n"
    " *\n"
    " * DO NOT \"TIGHTEN\" THIS TEST.  It was tried, 2026-09-14, and it is a large\n"
    " * REGRESSION on the GPU.  The bare threshold is conservative: it sends every\n"
    " * codepoint above U+02FF down the cluster walk, and on UTF8test2.txt 66.34%\n"
    " * of those walks turn out to be unnecessary (the word holds a high codepoint\n"
    " * but nothing that clusters).  Replacing the one compare with the precise\n"
    " * question u32_cl_next() asks -- extend, ZWJ, regional indicator, conjoining\n"
    " * Hangul -- removes exactly those walks and was byte-exact on 164,540,744\n"
    " * (word, rule) pairs.  It still lost, on an fpga.local GTX 1080, both arms\n"
    " * built from one tree differing in this object alone:\n"
    " *\n"
    " *      cluster-sensitive rules (38,370)  45.84 -> 28.12 Mh/s   1.63x SLOWER\n"
    " *      cluster-free rules      (61,625) 112.85 -> 75.26 Mh/s   1.50x SLOWER\n"
    " *      byte mode (control)              349.73 -> 350.07 Mh/s  unchanged\n"
    " *\n"
    " * Two lessons, and the second is the useful one.  First, the precise test is\n"
    " * not cheap: u32_is_extend() reaches u32_is_mark(), a binary search over 290\n"
    " * ranges, so the gate costs a divergent branchy table probe per codepoint in\n"
    " * place of one compare -- to save a walk whose own fast path is two compares\n"
    " * per codepoint.  The gate can never save more than about one compare per\n"
    " * codepoint, so there is no version of this that pays.\n"
    " *\n"
    " * Second, and this is why the number to chase is elsewhere: the CLUSTER-FREE\n"
    " * half slowed down by the same factor.  Those rules do not call cl_start() or\n"
    " * cl_count() at all, so a per-call cost cannot explain it.  The regression is\n"
    " * global -- kernel size and occupancy -- which says the 2.5x cluster\n"
    " * multiplier does not live in this gate either way.\n"
    " *\n"
    " * It used to be a bare `>= U32_MARK_LO` threshold, which was CORRECT but\n"
    " * conservative: it sent every codepoint above U+02FF down the cluster walk,\n"
    " * and 69.7% of the words that took the walk on UTF8test2.txt contained\n"
    " * nothing that clusters at all.  The precise test below asks the question\n"
    " * cl_next actually asks, and keeps the one-comparison exit for ASCII.\n"
    " *\n"
    " * Marks alone would be WRONG here, not merely slower -- an emoji-ZWJ\n"
    " * sequence carries no combining mark and still clusters, as does a flag\n"
    " * pair and a Hangul syllable.  The predicate mirrors every branch of\n"
    " * u32_cl_next and must be changed with it. */\n"
    "U32_SI int u32_cl_all_plain(U32_BUF const uint *b, int n)\n"
    "{\n"
    "    for (int i = 0; i < n; i++) if (b[i] >= U32_MARK_LO) return 0;\n"
    "    return 1;\n"
    "}\n"
    "\n"
    "U32_SI int u32_cl_start(U32_BUF const uint *b, int n, int k)\n"
    "{\n"
    "    int i = 0;\n"
    "    if (u32_cl_all_plain(b, n)) return k < n ? k : n;\n"
    "    while (i < n && k > 0) { i = u32_cl_next(b, n, i); k--; }\n"
    "    return i;\n"
    "}\n"
    "\n"
    "U32_SI int u32_cl_count(U32_BUF const uint *b, int n)\n"
    "{\n"
    "    int i = 0, c = 0;\n"
    "    if (u32_cl_all_plain(b, n)) return n;\n"
    "    while (i < n) { i = u32_cl_next(b, n, i); c++; }\n"
    "    return c;\n"
    "}\n"
    "\n"
    "/* Reverse the half-open span [i,j).  Reversing two spans and then the whole\n"
    " * run swaps two clusters of DIFFERENT lengths without a scratch buffer. */\n"
    "U32_SI void u32_rev_span(U32_BUF uint *b, int i, int j)\n"
    "{\n"
    "    for (j--; i < j; i++, j--) { uint t = b[i]; b[i] = b[j]; b[j] = t; }\n"
    "}\n"
    "\n"
    "U32_SI void u32_cl_swap(U32_BUF uint *b, int n, int k1, int k2)\n"
    "{\n"
    "    int a0 = u32_cl_start(b, n, k1), a1 = u32_cl_start(b, n, k1 + 1);\n"
    "    int b0 = u32_cl_start(b, n, k2), b1 = u32_cl_start(b, n, k2 + 1);\n"
    "    if (a1 > b0) return;\n"
    "    u32_rev_span(b, a0, a1); u32_rev_span(b, a1, b0); u32_rev_span(b, b0, b1);\n"
    "    u32_rev_span(b, a0, b1);\n"
    "}\n"
    "\n"
    "/* ==== case layer ======================================================\n"
    " *\n"
    " * Tables are GENERATED from the CPU engine's own headers by\n"
    " * gen_u32_tables.py and verified element-by-element against them, because\n"
    " * hand-transcribing 6,858 entries is the defect class that check exists to\n"
    " * remove.\n"
    " */\n"
    "/* ---- WHY THE TWO CASE ARRAYS ARE A KERNEL ARGUMENT ------------------\n"
    " *\n"
    " * They used to be CL_CONSTANT like the rest.  MEASURED on a GTX 1080:\n"
    " *\n"
    " *     ptxas error : File uses too much global constant data\n"
    " *                   (0x132c4 bytes, 0x10000 max)\n"
    " *\n"
    " * 78,532 against NVIDIA's 65,536-byte constant bank.  The rules program\n"
    " * already carried ~47.8 KB of __constant before this walker was added -- the\n"
    " * algorithm tables in gpu_common.cl -- so the 30,696 bytes here pushed it\n"
    " * 13 KB over.  `u32_case_up` and `u32_case_lo` are 26,048 of those 30,696, so\n"
    " * moving just those two to __global brings this walker's constant use to\n"
    " * 4,648 and the program to ~52.5 KB: 13 KB of headroom rather than none.\n"
    " *\n"
    " * int16 DELTAS were measured first and REJECTED: the range is [-42319, 42319]\n"
    " * and **183 of 6,512 entries do not fit in int16** (the astral blocks --\n"
    " * Deseret, Osage, Adlam -- have large case offsets).  A delta table with an\n"
    " * escape list would also have saved only 13,024 bytes, landing at 65,508\n"
    " * against a 65,536 limit, which is 28 bytes of headroom and not a design.\n"
    " *\n"
    " * The two arrays arrive CONCATENATED in one buffer -- up at [0 .. N-1], lo at\n"
    " * [N .. 2N-1] -- so exactly one pointer threads through, rather than two or a\n"
    " * struct.  `ct` is that pointer and it is passed down from the kernel.\n"
    " *\n"
    " * The COST is that a case lookup now reads global memory instead of the\n"
    " * constant cache.  The tables are 26 KB and hot, so they should live in L1/L2,\n"
    " * but that is an expectation and not a measurement; it is named in the run\n"
    " * report as a thing to watch rather than claimed to be free.\n"
    " */\n"
    "#define U32_CT_UP(ct, ix)  ((ct)[(ix)])\n"
    "#define U32_CT_LO(ct, ix)  ((ct)[U32_CASE_N + (ix)])\n"
    "\n"
    "U32_SI int u32_case_find(uint c)   /* index into the case tables, or -1 */\n"
    "{\n"
    "    int lo = 0, hi = U32_CASE_NRANGES - 1;\n"
    "\n"
    "    /* Bounds first.  Without it every ASCII digit and punctuation character\n"
    "     * paid a full binary search, and case-heavy rules over an alphanumeric\n"
    "     * wordlist ran 19% slower on the CPU for exactly that reason. */\n"
    "    if (c < u32_case_ranges[0] ||\n"
    "        c > u32_case_ranges[3 * (U32_CASE_NRANGES - 1) + 1]) return -1;\n"
    "\n"
    "    while (lo <= hi) {\n"
    "        int mid = (lo + hi) >> 1;\n"
    "        if (c < u32_case_ranges[3 * mid])          hi = mid - 1;\n"
    "        else if (c > u32_case_ranges[3 * mid + 1]) lo = mid + 1;\n"
    "        else return (int)(u32_case_ranges[3 * mid + 2] +\n"
    "                          (c - u32_case_ranges[3 * mid]));\n"
    "    }\n"
    "    return -1;\n"
    "}\n"
    "\n"
    "/* turkish is ALWAYS 0 here -- variant 0 only, see the header.  It is kept as\n"
    " * a parameter so the arms read the same as the CPU's and a future variant\n"
    " * pass has somewhere to go. */\n"
    "U32_SI uint u32_upper(uint c, int turkish, U32_GLOBAL const uint *ct)\n"
    "{\n"
    "    int ix;\n"
    "    if (c == U32_SMALL_I) return turkish ? U32_CAPITAL_I_DOT : U32_CAPITAL_I;\n"
    "    /* U+0131 -> I is UNAMBIGUOUS (both locales agree), so ruleproc32.c states\n"
    "     * it as a special case.  Here the generated table already carries it --\n"
    "     * up(U+0131) = U+0049, verified against latin_case.h -- so the branch\n"
    "     * would be dead weight in a function this hot.  Said rather than left to\n"
    "     * be rediscovered, because the two functions are meant to read as\n"
    "     * translations of each other. */\n"
    "    if (c >= 'a' && c <= 'z') return c - 32u;\n"
    "    if (c < 0x80u) return c;\n"
    "    ix = u32_case_find(c);\n"
    "    if (ix < 0) return c;\n"
    "    return U32_CT_UP(ct, ix) ? U32_CT_UP(ct, ix) : c;\n"
    "}\n"
    "\n"
    "U32_SI uint u32_lower(uint c, int turkish, U32_GLOBAL const uint *ct)\n"
    "{\n"
    "    int ix;\n"
    "    if (c == U32_CAPITAL_I) return turkish ? U32_SMALL_DOTLESS : U32_SMALL_I;\n"
    "    /* U+0130 lowercases to i + COMBINING DOT ABOVE in full Unicode, which is\n"
    "     * length-changing and therefore EXCLUDED from the generated table -- so\n"
    "     * the table answer is U+0130 unchanged and the lookup below cannot supply\n"
    "     * this.  ruleproc32.c's cp_lower states the simple 1:1 answer, plain i,\n"
    "     * and this is that line.\n"
    "     *\n"
    "     * Found by the host twin, not by inspection: 105 diffs in 49,985,000 pairs\n"
    "     * over HashMob.10k x 5,000 UTF-8 words, every one of them a `c`/`l`/`E`\n"
    "     * after a `+N`/`-N` had walked a codepoint onto U+0130.  A 1-in-476,000\n"
    "     * divergence that no per-rule spot check would have shown, and the reason\n"
    "     * the twin exists. */\n"
    "    if (c == U32_CAPITAL_I_DOT) return U32_SMALL_I;\n"
    "    if (c >= 'A' && c <= 'Z') return c + 32u;\n"
    "    if (c < 0x80u) return c;\n"
    "    ix = u32_case_find(c);\n"
    "    if (ix < 0) return c;\n"
    "    return U32_CT_LO(ct, ix) ? U32_CT_LO(ct, ix) : c;\n"
    "}\n"
    "\n"
    "/* Index into u32_expand of the entry for c, or -1. */\n"
    "U32_SI int u32_expand_find(uint c)\n"
    "{\n"
    "    int lo = 0, hi = U32_EXPAND_N - 1;\n"
    "    int stride = 2 + U32_EXPAND_MAX;\n"
    "\n"
    "    if (c < U32_EXPAND_LO || c > U32_EXPAND_HI) return -1;\n"
    "    while (lo <= hi) {\n"
    "        int mid = (lo + hi) >> 1;\n"
    "        if (c < u32_expand[mid * stride])      hi = mid - 1;\n"
    "        else if (c > u32_expand[mid * stride]) lo = mid + 1;\n"
    "        else return mid;\n"
    "    }\n"
    "    return -1;\n"
    "}\n"
    "\n"
    "/* A ligature has no 1:1 mapping in EITHER direction -- its uppercase grows\n"
    " * and its lowercase is itself -- so asking u32_upper alone would call it\n"
    " * caseless and `c` would walk straight past one looking for a letter. */\n"
    "U32_SI int u32_is_cased(uint c, int turkish, U32_GLOBAL const uint *ct)\n"
    "{\n"
    "    if (u32_expand_find(c) >= 0) return 1;\n"
    "    return u32_upper(c, turkish, ct) != c || u32_lower(c, turkish, ct) != c;\n"
    "}\n"
    "\n"
    "/* Uppercase that is allowed to GROW: eszett -> SS is the one mapping in the\n"
    " * covered ranges that changes length, and no 1:1 table can hold it.  Writes 1\n"
    " * or 3 codepoints and returns the count.  Only the whole-string verbs use it;\n"
    " * a position-indexed verb keeps the 1:1 map, because growing a character\n"
    " * underneath an index would move every position the rest of the rule refers\n"
    " * to.  So `u` on a word with an eszett gives ...SS..., while a toggle AT a\n"
    " * position leaves the eszett alone. */\n"
    "U32_SI int u32_upper_full(uint c, int turkish, U32_SCRATCH uint *out,\n"
    "                          U32_GLOBAL const uint *ct)\n"
    "{\n"
    "    int e = u32_expand_find(c);\n"
    "    int stride = 2 + U32_EXPAND_MAX;\n"
    "    if (e >= 0) {\n"
    "        int cnt = (int)u32_expand[e * stride + 1];\n"
    "        for (int k = 0; k < cnt; k++) out[k] = u32_expand[e * stride + 2 + k];\n"
    "        return cnt;\n"
    "    }\n"
    "    out[0] = u32_upper(c, turkish, ct);\n"
    "    return 1;\n"
    "}\n"
    "\n"
    "/* Uppercase the whole buffer in place, growing where a mapping expands.  ONE\n"
    " * pass over the buffer, which is the whole point.  Returns the new length or\n"
    " * U32_ERR_NOROOM.\n"
    " *\n"
    " * MEASURED, fpga.local GTX 1080, 38,370 distinct rules x 55,000 UTF8test2\n"
    " * words: throughput on this kernel tracks the NUMBER OF PASSES over the\n"
    " * codepoint buffer and almost nothing else.  `l` and `t` traverse once and both\n"
    " * run 233.7 Mh/s; `u` traversed twice -- an expansion pre-scan, then the map --\n"
    " * and ran 123.9, a ratio of 1.886 against a predicted 2.  Deleting the pre-scan\n"
    " * took it to 262.8.\n"
    " *\n"
    " * And making that pass CHEAPER does nothing: a block bitmap derived from\n"
    " * u32_expand, which removed 91.7%% of the pre-scan's binary searches, measured\n"
    " * 1.00x on every verb.  It was reverted.  The binary search was never the cost;\n"
    " * the traversal was.  Count passes before proposing anything here.\n"
    " *\n"
    " * Expansion is handled inline instead.  u32_upper_full returns 1 for every\n"
    " * codepoint that does not grow -- all but 0.0127%% of a multi-script corpus --\n"
    " * and the shift runs only for the rest.  Growth cannot cascade, since no\n"
    " * expansion output is itself an expanding codepoint, so `i` skips what was just\n"
    " * written exactly as the backwards write did. */\n"
    "U32_SI int u32_upper_all(U32_BUF uint *b, int n, int turkish,\n"
    "                         U32_GLOBAL const uint *ct)\n"
    "{\n"
    "    uint tmp[U32_EXPAND_MAX];\n"
    "    int i, j, k, len = n;\n"
    "\n"
    "    for (i = 0; i < len; i++) {\n"
    "        k = u32_upper_full(b[i], turkish, tmp, ct);\n"
    "        if (k == 1) { b[i] = tmp[0]; continue; }\n"
    "        if (len + k - 1 > U32_BUF_LIMIT) return U32_ERR_NOROOM;\n"
    "        for (j = len - 1; j > i; j--) b[j + k - 1] = b[j];\n"
    "        for (j = 0; j < k; j++)      b[i + j] = tmp[j];\n"
    "        len += k - 1;\n"
    "        i   += k - 1;\n"
    "    }\n"
    "    return len;\n"
    "}\n"
    "\n"
    "/* Greek sigma is the one case mapping that depends on WHERE the character\n"
    " * sits: a sigma ending a word is U+03C2, anywhere else U+03C3.  The table\n"
    " * cannot express that, so it maps capital sigma to the medial form and this\n"
    " * runs afterwards over a whole-word lowercase.  Only the whole-string verbs\n"
    " * call it; a single-position toggle has no word to be at the end of. */\n"
    "U32_SI void u32_final_sigma(U32_BUF uint *b, int n, int turkish,\n"
    "                            U32_GLOBAL const uint *ct)\n"
    "{\n"
    "    for (int i = 0; i < n; i++) {\n"
    "        if (b[i] != U32_SMALL_SIGMA) continue;\n"
    "        if (i + 1 == n || !u32_is_cased(b[i + 1], turkish, ct))\n"
    "            b[i] = U32_FINAL_SIGMA;\n"
    "    }\n"
    "}\n"
    "\n"
    "/* Character-class membership, over a CODEPOINT.  The 15x32 bitmap in the\n"
    " * common source is indexed by BYTE, so a codepoint above 0xff cannot be in\n"
    " * any class except ALL and HIGH.  Mirrors RULE_CLASS_MATCH_CP in\n"
    " * ../rule_ops.h, which is shared verbatim by the two CPU engines. */\n"
    "U32_SI int u32_class_match(uchar cb, uint ch)\n"
    "{\n"
    "    if (ch > 0xffu) {\n"
    "        uchar which = (uchar)(cb & 0x7f);\n"
    "        int in = (which == 15 || which == 14) ? 1 : 0;   /* ALL, HIGH */\n"
    "        return in ^ (int)((cb >> 7) & 1);\n"
    "    }\n"
    "    return rule_class_match(cb, (uchar)ch);\n"
    "}\n"
    "\n"
    "\n"
    "/* ==== the per-word class, and the engine predicate ===================\n"
    " *\n"
    " * These live in the SHARED body rather than in the kernel file so that\n"
    " * both backends AND both host tests get one copy.  pick_engine already\n"
    " * exists in three places -- mdxfind.c, procrule.c (token-for-token,\n"
    " * because procrule is the oracle) and gpu_u32_wire_hosttest.c (on purpose,\n"
    " * so the test asserts agreement rather than assuming it).  A fourth and\n"
    " * fifth copy, one per backend, is where a divergence would actually hide.\n"
    " */\n"
    "#define U32_CLASS_A   0u   /* ASCII or empty -- decodable, not wide */\n"
    "#define U32_CLASS_W   1u   /* HI|UTF8        -- decodable, wide     */\n"
    "#define U32_CLASS_I   2u   /* HI alone       -- NOT decodable       */\n"
    "\n"
    "/* mdxfind.c's pick_engine is:\n"
    " *\n"
    " *     wide     = ((wenc & U8C_WIDE) == U8C_WIDE);\n"
    " *     u32_must = (u32_can && !byte_can);\n"
    " *     if ((wide || u32_must) && u32_can && U8C_DECODABLE(wenc)) return 1;\n"
    " *     if (byte_can) return 0;\n"
    " *     return -1;\n"
    " *\n"
    " * The word axis collapses to the three classes above because classify_utf8\n"
    " * guarantees exactly one of ASCII / HI for n > 0 and UTF8 only in company\n"
    " * with HI: `wide` is class == W, and `decodable` is class != I.\n"
    " *\n"
    " * Returns 1 = UTF-32, 0 = byte, -1 = neither (the pair is skipped, which is\n"
    " * what the CPU counts in Unreachable). */\n"
    "U32_SI int u32_pick_engine(uint wclass, int u32_can, int byte_can)\n"
    "{\n"
    "    int wide      = (wclass == U32_CLASS_W);\n"
    "    int decodable = (wclass != U32_CLASS_I);\n"
    "    int u32_must  = (u32_can && !byte_can);\n"
    "\n"
    "    if ((wide || u32_must) && u32_can && decodable) return 1;\n"
    "    if (byte_can) return 0;\n"
    "    return -1;\n"
    "}\n"
    "\n"
    "\n"
    "/* Second half of rule_offset: capability bits over a 30-bit offset.\n"
    " * A rule program larger than 2^30 would collide with these; the host asserts\n"
    " * against it before it sets a bit. */\n"
    "#define U32_R_HASFORM 0x80000000u   /* a UTF-32 form exists for this rule   */\n"
    "#define U32_R_BYTEOK  0x40000000u   /* the byte compiler accepted this rule */\n"
    "#define U32_R_OFFMASK 0x3fffffffu\n"
    "\n"
    "/* Per-word class values live in gpu_u32_walker.inc beside u32_pick_engine,\n"
    " * which is the only thing that interprets them. */\n"
    "\n"
    "#define U32_OFF_MASK  0x3fffffffu\n"
    "#define U32_TAG_SHIFT 30\n"
    "\n"
    "/* U32_OUT_BYTES (the encoder's worst case, 4 UTF-8 bytes per codepoint) and\n"
    " * U32_SLOT_BYTES are defined ONCE, at the top of this file beside\n"
    " * U32_BUF_ELEMS, because the Metal host derives its scratch-pool stride from\n"
    " * the same formula.  A second identical #define sat here for one revision;\n"
    " * it was legal and it was exactly the kind of thing that later drifts. */\n"
    "\n"
    "/* ==== the shared per-lane body ========================================\n"
    " *\n"
    " * Staged input -> engine choice -> walk -> UTF-8 bytes out.  Returns the\n"
    " * candidate length in BYTES, or negative:\n"
    " *   -1  the pair is skipped (no engine, or a rejection op fired)\n"
    " *   -2  the walker ran out of buffer (DEFINED divergence above\n"
    " *       U32_BUF_LIMIT, not an error -- see gpu_u32_walker.inc)\n"
    " *\n"
    " * `out` receives the candidate bytes.  For the byte engine that is the walker\n"
    " * buffer itself and no copy happens; for the UTF-32 engine it is the encode\n"
    " * target.  Both are caller-owned so the register/private-memory cost is\n"
    " * visible at the call site instead of hidden here.\n"
    " */\n"
    "/* ==== the walker ======================================================\n"
    " *\n"
    " * apply_rule32:\n"
    " *   prog: pointer to the packed uint32 stream, already offset by the caller;\n"
    " *         the first word is the first opcode.  Terminated by U32_END.\n"
    " *   buf:  U32_BUF_ELEMS uints, pre-staged with the input in buf[0..len-1].\n"
    " *   mem:  U32_BUF_ELEMS uints of scratch for the memory verbs.  Passed in\n"
    " *         rather than declared here so the CALLER picks the address space --\n"
    " *         Metal cannot afford 8 KB of `thread` for it on top of buf.\n"
    " *   len:  initial length in CODEPOINTS.\n"
    " *\n"
    " * Returns the new length in codepoints, or U32_REJECTED / U32_ERR_NOROOM.\n"
    " *\n"
    " * ROOM() mirrors applyrule32's macro and its purpose: every growth path goes\n"
    " * through one place, because a bound living in one file and the buffer in\n"
    " * another is how the byte engine once wrote 40 KB into a 20 KB buffer.\n"
    " *\n"
    " * The 256-op cap on the loop matches the byte walker's, not the CPU's -- the\n"
    " * CPU walks to the terminator.  A rule longer than 256 ops is not reachable\n"
    " * from packrule32's own limits in practice; the cap is there so a corrupt\n"
    " * stream cannot spin a lane forever.\n"
    " */\n"
    "#define U32_ROOM(need) do { if ((need) > U32_BUF_LIMIT) return U32_ERR_NOROOM; } while (0)\n"
    "\n"
    "U32_SI int apply_rule32(U32_GLOBAL const uint *prog,\n"
    "                        U32_BUF uint *buf, U32_BUF uint *mem, int len,\n"
    "                        U32_GLOBAL const uint *ct)\n"
    "{\n"
    "    int k = 0;\n"
    "    int memlen = 0;         /* per-invocation, exactly as applyrule32 resets it */\n"
    "    const int turkish = 0;  /* variant 0 only -- see the header */\n"
    "    int i, j;\n"
    "\n"
    "    for (int nop = 0; nop < 256; nop++) {\n"
    "        uint op = prog[k++];\n"
    "        if (op == U32_END) break;\n"
    "\n"
    "        switch (op) {\n"
    "            case RULE_OP_NOOP:\n"
    "            case RULE_OP_NOOP_SP:\n"
    "            case RULE_OP_NOOP_TAB:\n"
    "            case RULE_OP_HASH_EXIT:\n"
    "            case RULE_OP_S_SPECIAL:\n"
    "                break;\n"
    "\n"
    "            /* ---- collapsed affix runs -------------------------------\n"
    "             * Appending is a straight copy to the tail.  Prepending must\n"
    "             * reproduce what N separate prepends do, and each one pushes in\n"
    "             * FRONT of the last, so `^1^2^3` yields 321 -- the operands land\n"
    "             * in REVERSE rule order.  Getting that backwards is silent. */\n"
    "            case RULE32_OP_APPEND_MULTI: {\n"
    "                int cnt = (int)prog[k++];\n"
    "                U32_ROOM(len + cnt);\n"
    "                for (int m = 0; m < cnt; m++) buf[len + m] = prog[k + m];\n"
    "                k += cnt; len += cnt;\n"
    "                break;\n"
    "            }\n"
    "            case RULE32_OP_PREPEND_MULTI: {\n"
    "                int cnt = (int)prog[k++];\n"
    "                U32_ROOM(len + cnt);\n"
    "                for (int m = len - 1; m >= 0; m--) buf[m + cnt] = buf[m];\n"
    "                for (int m = 0; m < cnt; m++) buf[m] = prog[k + cnt - 1 - m];\n"
    "                k += cnt; len += cnt;\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_APPEND: {\n"
    "                uint cp = prog[k++];\n"
    "                U32_ROOM(len + 1); buf[len++] = cp; break;\n"
    "            }\n"
    "            case RULE_OP_PREPEND: {\n"
    "                uint cp = prog[k++];\n"
    "                U32_ROOM(len + 1);\n"
    "                for (i = len; i > 0; i--) buf[i] = buf[i - 1];\n"
    "                buf[0] = cp; len++; break;\n"
    "            }\n"
    "\n"
    "            /* ---- arithmetic on a CODEPOINT, not a byte ---------------\n"
    "             * This is the deliberate semantic change: + - L R operate on the\n"
    "             * full codepoint, so L on U+0041 gives U+0082 where the byte\n"
    "             * engine gave 0x82.  These verbs are also the ONLY way to produce\n"
    "             * a codepoint UTF-8 cannot encode, and u32_encode drops exactly\n"
    "             * those while emitting the rest of the line.\n"
    "             *\n"
    "             * Note the index is a CODEPOINT index, not a cluster index -- that\n"
    "             * is applyrule32's behaviour, not an omission here. */\n"
    "            case RULE_OP_INC:     { int y = (int)prog[k++]; if (y < len) buf[y]++; break; }\n"
    "            case RULE_OP_DEC:     { int y = (int)prog[k++]; if (y < len) buf[y]--; break; }\n"
    "            case RULE_OP_BIT_SHL: { int y = (int)prog[k++]; if (y < len) buf[y] <<= 1; break; }\n"
    "            case RULE_OP_BIT_SHR: { int y = (int)prog[k++]; if (y < len) buf[y] >>= 1; break; }\n"
    "\n"
    "            /* `.N` at the LAST position leaves the character alone.  The byte\n"
    "             * engine reads its NUL terminator there and writes a NUL, which is\n"
    "             * an artefact of a NUL-terminated buffer; applyrule32 deliberately\n"
    "             * does not reproduce it, because the answer then depended on the\n"
    "             * previous candidate in a reused static buffer. */\n"
    "            case RULE_OP_REPL_NEXT: { int y = (int)prog[k++];\n"
    "                if (y < len - 1) buf[y] = buf[y + 1]; break; }\n"
    "            case RULE_OP_REPL_PREV: { int y = (int)prog[k++];\n"
    "                if (y < len && y > 0) buf[y] = buf[y - 1]; break; }\n"
    "\n"
    "            /* ---- memory ---------------------------------------------- */\n"
    "            case RULE_OP_MEM_STORE:\n"
    "                for (i = 0; i < len; i++) mem[i] = buf[i];\n"
    "                memlen = len; break;\n"
    "            case RULE_OP_MEM_APP:\n"
    "                if (memlen > 0) { U32_ROOM(len + memlen);\n"
    "                    for (i = 0; i < memlen; i++) buf[len + i] = mem[i];\n"
    "                    len += memlen; }\n"
    "                break;\n"
    "            case RULE_OP_MEM_PRE:\n"
    "                if (memlen > 0) { U32_ROOM(len + memlen);\n"
    "                    for (i = len - 1; i >= 0; i--) buf[i + memlen] = buf[i];\n"
    "                    for (i = 0; i < memlen; i++) buf[i] = mem[i];\n"
    "                    len += memlen; }\n"
    "                break;\n"
    "            case RULE_OP_MEM_REJ:\n"
    "                if (memlen == len) {\n"
    "                    for (i = 0; i < len; i++) if (buf[i] != mem[i]) break;\n"
    "                    if (i == len) return U32_REJECTED;\n"
    "                }\n"
    "                break;\n"
    "            /* `X N M I`: insert M of memory from OFFSET N, at position I.\n"
    "             * REJECTS on each of no-memory / zero-count / position past end /\n"
    "             * offset past memory / range overruns memory; only the\n"
    "             * result-too-long case clamps.  Clamping the others instead is a\n"
    "             * measured divergence (MX042 on aB3 gave aBaB33 where the oracle\n"
    "             * rejects).  Memory is counted in CODEPOINTS while the insert\n"
    "             * position is a CLUSTER index, as in applyrule32. */\n"
    "            case RULE_OP_MEM_INSERT: {\n"
    "                int off = (int)prog[k++], cnt = (int)prog[k++], at = (int)prog[k++];\n"
    "                int nc = u32_cl_count(buf, len), a;\n"
    "                if (memlen < 1 || cnt < 1 || at > nc ||\n"
    "                    off > memlen || (off + cnt) > memlen) return U32_REJECTED;\n"
    "                if (len + cnt > U32_BUF_LIMIT) cnt = U32_BUF_LIMIT - len;\n"
    "                if (cnt < 1) break;\n"
    "                a = u32_cl_start(buf, len, at);\n"
    "                for (i = len - 1; i >= a; i--) buf[i + cnt] = buf[i];\n"
    "                for (i = 0; i < cnt; i++)      buf[a + i] = mem[off + i];\n"
    "                len += cnt;\n"
    "                break;\n"
    "            }\n"
    "\n"
    "            /* ---- rejection ------------------------------------------\n"
    "             * Length is a count of CLUSTERS and of the CURRENT buffer, not\n"
    "             * the original: `$a _5` on a 4-cluster word must survive.  And\n"
    "             * `<N` / `>N` follow john -- reject unless LESS / GREATER than N\n"
    "             * -- which is the opposite of what an earlier reading had. */\n"
    "            case RULE_OP_REJ_LEN_NE: { int y = (int)prog[k++];\n"
    "                if (y != u32_cl_count(buf, len)) return U32_REJECTED; break; }\n"
    "            case RULE_OP_REJ_LEN_GE: { int y = (int)prog[k++];\n"
    "                if (u32_cl_count(buf, len) >= y) return U32_REJECTED; break; }\n"
    "            case RULE_OP_REJ_LEN_LE: { int y = (int)prog[k++];\n"
    "                if (u32_cl_count(buf, len) <= y) return U32_REJECTED; break; }\n"
    "            case RULE_OP_REJ_AT_CHR: { int y = (int)prog[k++]; uint cp = prog[k++];\n"
    "                if (y >= len || buf[y] != cp) return U32_REJECTED; break; }\n"
    "            case RULE_OP_REJ_CNT_CHR: { int y = (int)prog[k++]; uint cp = prog[k++];\n"
    "                int cnt = 0;\n"
    "                for (i = 0; i < len; i++) if (buf[i] == cp) cnt++;\n"
    "                if (cnt < y) return U32_REJECTED; break; }\n"
    "            case RULE_OP_REJ_HAS: { uint cp = prog[k++];\n"
    "                for (i = 0; i < len; i++) if (buf[i] == cp) return U32_REJECTED;\n"
    "                break; }\n"
    "            case RULE_OP_REJ_NHAS: { uint cp = prog[k++];\n"
    "                for (i = 0; i < len; i++) if (buf[i] == cp) break;\n"
    "                if (i >= len) return U32_REJECTED; break; }\n"
    "            case RULE_OP_REJ_FIRST: { uint cp = prog[k++];\n"
    "                if (len > 0 && buf[0] != cp) return U32_REJECTED; break; }\n"
    "            case RULE_OP_REJ_LAST: { uint cp = prog[k++];\n"
    "                if (len > 0 && buf[len - 1] != cp) return U32_REJECTED; break; }\n"
    "\n"
    "            /* ---- substitution and purge, codepoint-indexed ---------- */\n"
    "            case RULE_OP_PURGE: { uint cp = prog[k++]; int d = 0;\n"
    "                for (i = 0; i < len; i++) if (buf[i] != cp) buf[d++] = buf[i];\n"
    "                len = d; break; }\n"
    "            case RULE_OP_SUB: { uint from = prog[k++], to = prog[k++];\n"
    "                for (i = 0; i < len; i++) if (buf[i] == from) buf[i] = to;\n"
    "                break; }\n"
    "\n"
    "            /* ---- whole-word case ------------------------------------\n"
    "             * The sigma pass is skipped unless a medial sigma was actually\n"
    "             * produced; folding the test into the mapping loop costs one\n"
    "             * compare per character instead of a second walk. */\n"
    "            case RULE_OP_LOWER: {\n"
    "                int sigma = 0;\n"
    "                for (i = 0; i < len; i++) {\n"
    "                    buf[i] = u32_lower(buf[i], turkish, ct);\n"
    "                    if (buf[i] == U32_SMALL_SIGMA) sigma = 1;\n"
    "                }\n"
    "                if (sigma) u32_final_sigma(buf, len, turkish, ct);\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_UPPER: {\n"
    "                int nl = u32_upper_all(buf, len, turkish, ct);\n"
    "                if (nl < 0) return U32_ERR_NOROOM;\n"
    "                len = nl; break;\n"
    "            }\n"
    "            /* `c`: lowercase the word, then UPPERCASE the first CASED\n"
    "             * codepoint, expanding if it is one of the growing forms.  Note\n"
    "             * this is uppercase, not Unicode TITLE case: the fi ligature gives\n"
    "             * FInd here, where title case would give Find. */\n"
    "            /* The hunt for the first cased codepoint rides along with the\n"
    "             * lowercase pass instead of walking the buffer a second time.  The\n"
    "             * old second loop breaks at that codepoint, which sounds cheap and\n"
    "             * is not: MEASURED on UTF8test2.txt, 63.20% of words carry NO cased\n"
    "             * codepoint at all, so the break never fires and the scan runs the\n"
    "             * whole word -- 33.8% of a full extra pass overall.  Traversals are\n"
    "             * what cost here, so that was a third of a verb for the same number\n"
    "             * of u32_is_cased calls.\n"
    "             *\n"
    "             * fc survives u32_final_sigma, which runs between the two: it maps\n"
    "             * sigma to final sigma and both are cased, so it can neither move\n"
    "             * nor create the first cased position.  buf[fc] is read AFTER that\n"
    "             * pass, exactly as the old second loop saw it. */\n"
    "            case RULE_OP_CAP: {\n"
    "                int sigma = 0, fc = -1;\n"
    "                for (i = 0; i < len; i++) {\n"
    "                    buf[i] = u32_lower(buf[i], turkish, ct);\n"
    "                    if (buf[i] == U32_SMALL_SIGMA) sigma = 1;\n"
    "                    if (fc < 0 && u32_is_cased(buf[i], turkish, ct)) fc = i;\n"
    "                }\n"
    "                if (sigma) u32_final_sigma(buf, len, turkish, ct);\n"
    "                if (fc >= 0) {\n"
    "                    uint ex[U32_EXPAND_MAX];\n"
    "                    int ec = u32_upper_full(buf[fc], turkish, ex, ct);\n"
    "                    if (ec == 1) buf[fc] = ex[0];\n"
    "                    else {\n"
    "                        U32_ROOM(len + ec - 1);\n"
    "                        for (j = len - 1; j > fc; j--) buf[j + ec - 1] = buf[j];\n"
    "                        for (j = 0; j < ec; j++) buf[fc + j] = ex[j];\n"
    "                        len += ec - 1;\n"
    "                    }\n"
    "                }\n"
    "                break;\n"
    "            }\n"
    "            /* `C`: UPPERCASE the word, then lowercase the first cased one. */\n"
    "            case RULE_OP_CAP_INV: {\n"
    "                int nl = u32_upper_all(buf, len, turkish, ct);\n"
    "                if (nl < 0) return U32_ERR_NOROOM;\n"
    "                len = nl;\n"
    "                for (i = 0; i < len; i++) {\n"
    "                    if (!u32_is_cased(buf[i], turkish, ct)) continue;\n"
    "                    buf[i] = u32_lower(buf[i], turkish, ct);\n"
    "                    break;\n"
    "                }\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_TOGGLE:\n"
    "                for (i = 0; i < len; i++) {\n"
    "                    uint u = u32_upper(buf[i], turkish, ct);\n"
    "                    buf[i] = (u != buf[i]) ? u : u32_lower(buf[i], turkish, ct);\n"
    "                }\n"
    "                break;\n"
    "            /* `TN` toggles the CLUSTER's BASE, not the Nth codepoint. */\n"
    "            case RULE_OP_TOGGLE_AT: {\n"
    "                int kk = (int)prog[k++];\n"
    "                int p = u32_cl_start(buf, len, kk);\n"
    "                if (kk < u32_cl_count(buf, len)) {\n"
    "                    uint u = u32_upper(buf[p], turkish, ct);\n"
    "                    buf[p] = (u != buf[p]) ? u : u32_lower(buf[p], turkish, ct);\n"
    "                }\n"
    "                break;\n"
    "            }\n"
    "            /* `E` / `eX` title case.  An already-uppercase letter at a word\n"
    "             * start IS the capital: keep it and mark the word started.  The\n"
    "             * earlier form lowercased it and left the flag clear, so the NEXT\n"
    "             * lowercase letter was capitalised instead -- Hello1 became\n"
    "             * hEllo1.  hashcat 6.2.5 and john both give Hello1. */\n"
    "            case RULE_OP_TITLE_SP:\n"
    "            case RULE_OP_TITLE_SEP: {\n"
    "                uint sep = (op == RULE_OP_TITLE_SEP) ? prog[k++] : (uint)' ';\n"
    "                int z = 0;\n"
    "                for (i = 0; i < len; i++) {\n"
    "                    uint ch = buf[i];\n"
    "                    if (ch == sep) { z = 0; }\n"
    "                    else if (u32_lower(ch, turkish, ct) != ch) {\n"
    "                        if (z == 0) z = 1;              /* already capitalised */\n"
    "                        else buf[i] = u32_lower(ch, turkish, ct);\n"
    "                    } else if (u32_upper(ch, turkish, ct) != ch) {\n"
    "                        if (z == 0) { z = 1; buf[i] = u32_upper(ch, turkish, ct); }\n"
    "                    }\n"
    "                    /* CASELESS characters -- digits, punctuation, `$`, `[` --\n"
    "                     * fall through UNTOUCHED and leave z alone.  An earlier\n"
    "                     * form of this arm set z on them and lowercased in the\n"
    "                     * final else, which turned `$HEX[` into `$Hex[` under\n"
    "                     * `E`: 9,516 divergences in 1,999,400 pairs, all from\n"
    "                     * this one arm.  There is no final else on purpose. */\n"
    "                }\n"
    "                break;\n"
    "            }\n"
    "\n"
    "            /* ---- cluster-indexed structural verbs ------------------- */\n"
    "            case RULE_OP_REVERSE: {\n"
    "                /* Two in-place passes and no scratch buffer: reverse each\n"
    "                 * cluster, then reverse the whole run.  Reversing by\n"
    "                 * codepoint put an Arabic fatha on the wrong letter and\n"
    "                 * turned a flag into a DIFFERENT flag. */\n"
    "                for (i = 0; i < len; ) { int e = u32_cl_next(buf, len, i);\n"
    "                    u32_rev_span(buf, i, e); i = e; }\n"
    "                u32_rev_span(buf, 0, len);\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_DUP:\n"
    "                U32_ROOM(len * 2);\n"
    "                for (i = 0; i < len; i++) buf[len + i] = buf[i];\n"
    "                len *= 2; break;\n"
    "            case RULE_OP_REFLECT: {\n"
    "                int e;\n"
    "                U32_ROOM(len * 2);\n"
    "                for (i = 0; i < len; i++) buf[len + i] = buf[i];\n"
    "                for (i = len; i < len * 2; ) { e = u32_cl_next(buf, len * 2, i);\n"
    "                    u32_rev_span(buf, i, e); i = e; }\n"
    "                u32_rev_span(buf, len, len * 2);\n"
    "                len *= 2; break;\n"
    "            }\n"
    "            /* `q` -- double every CLUSTER, so a pointed letter is doubled\n"
    "             * with its points rather than the mark being doubled alone. */\n"
    "            case RULE_OP_DUP_EACH: {\n"
    "                int nc = u32_cl_count(buf, len), w, a, b2, c2;\n"
    "                U32_ROOM(len * 2);\n"
    "                w = len * 2;\n"
    "                for (c2 = nc - 1; c2 >= 0; c2--) {\n"
    "                    a = u32_cl_start(buf, len, c2); b2 = u32_cl_start(buf, len, c2 + 1);\n"
    "                    for (j = 0; j < 2; j++) { int t2;\n"
    "                        for (t2 = b2 - 1; t2 >= a; t2--) buf[--w] = buf[t2]; }\n"
    "                }\n"
    "                len *= 2; break;\n"
    "            }\n"
    "            case RULE_OP_ROT_L:\n"
    "                if (u32_cl_count(buf, len) > 1) {\n"
    "                    int c1 = u32_cl_start(buf, len, 1);\n"
    "                    u32_rev_span(buf, 0, c1); u32_rev_span(buf, c1, len);\n"
    "                    u32_rev_span(buf, 0, len);\n"
    "                }\n"
    "                break;\n"
    "            case RULE_OP_ROT_R:\n"
    "                if (u32_cl_count(buf, len) > 1) {\n"
    "                    int a = u32_cl_start(buf, len, u32_cl_count(buf, len) - 1);\n"
    "                    u32_rev_span(buf, 0, a); u32_rev_span(buf, a, len);\n"
    "                    u32_rev_span(buf, 0, len);\n"
    "                }\n"
    "                break;\n"
    "            case RULE_OP_DROP_FIRST: {\n"
    "                int e;\n"
    "                if (!len) break;\n"
    "                e = u32_cl_next(buf, len, 0);\n"
    "                for (i = 0; i + e < len; i++) buf[i] = buf[i + e];\n"
    "                len -= e; break;\n"
    "            }\n"
    "            case RULE_OP_DROP_LAST: {\n"
    "                int nc;\n"
    "                if (!len) break;\n"
    "                nc = u32_cl_count(buf, len);\n"
    "                len = u32_cl_start(buf, len, nc - 1);\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_SWAP_FRONT:\n"
    "                if (u32_cl_count(buf, len) > 1) u32_cl_swap(buf, len, 0, 1);\n"
    "                break;\n"
    "            case RULE_OP_SWAP_BACK: {\n"
    "                int nc = u32_cl_count(buf, len);\n"
    "                if (nc > 1) u32_cl_swap(buf, len, nc - 2, nc - 1);\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_SWAP_AT: {\n"
    "                int p = (int)prog[k++], q = (int)prog[k++];\n"
    "                int nc = u32_cl_count(buf, len);\n"
    "                if (p < nc && q < nc && p != q)\n"
    "                    u32_cl_swap(buf, len, p < q ? p : q, p < q ? q : p);\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_DEL_AT: {\n"
    "                int kk = (int)prog[k++], a, b2, w;\n"
    "                if (kk >= u32_cl_count(buf, len)) break;\n"
    "                a = u32_cl_start(buf, len, kk);\n"
    "                b2 = u32_cl_start(buf, len, kk + 1);\n"
    "                for (w = a; w + (b2 - a) < len; w++) buf[w] = buf[w + (b2 - a)];\n"
    "                len -= (b2 - a);\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_TRUNC: {\n"
    "                int kk = (int)prog[k++];\n"
    "                if (kk < u32_cl_count(buf, len)) len = u32_cl_start(buf, len, kk);\n"
    "                break;\n"
    "            }\n"
    "            /* Insert tests position >= length, so inserting AT the length\n"
    "             * appends rather than silently doing nothing. */\n"
    "            case RULE_OP_INSERT: {\n"
    "                int kk = (int)prog[k++]; uint cp = prog[k++];\n"
    "                int p = u32_cl_start(buf, len, kk);\n"
    "                if (u32_cl_count(buf, len) >= kk) { U32_ROOM(len + 1);\n"
    "                    for (i = len; i > p; i--) buf[i] = buf[i - 1];\n"
    "                    buf[p] = cp; len++; }\n"
    "                break;\n"
    "            }\n"
    "            /* `oNX` replaces the whole CLUSTER at N with ONE codepoint, so it\n"
    "             * can SHRINK the buffer when that cluster was multi-codepoint. */\n"
    "            case RULE_OP_OVERWRITE: {\n"
    "                int kk = (int)prog[k++]; uint cp = prog[k++];\n"
    "                int p = kk, a, b2, w;\n"
    "                if (kk < u32_cl_count(buf, len)) {\n"
    "                    a = u32_cl_start(buf, len, kk);\n"
    "                    b2 = u32_cl_start(buf, len, kk + 1);\n"
    "                    buf[a] = cp;\n"
    "                    for (w = a + 1; w + (b2 - a - 1) < len; w++)\n"
    "                        buf[w] = buf[w + (b2 - a - 1)];\n"
    "                    len -= (b2 - a - 1);\n"
    "                }\n"
    "                /* Special case carried over from ruleproc.c: overwriting\n"
    "                 * position 0 of an EMPTY buffer APPENDS instead of doing\n"
    "                 * nothing, so `o0X` on a candidate some earlier verb emptied\n"
    "                 * still yields X.  Omitting it is what made every\n"
    "                 * `[ [ ... o0q ...` and `] ] ... o0q ...` rule in\n"
    "                 * HashMob.100k.rule diverge on short words -- 9 distinct\n"
    "                 * rules, and each looked like a cluster bug rather than a\n"
    "                 * missing two-line special case. */\n"
    "                if (p == 0 && len == 0) { U32_ROOM(1); buf[0] = cp; len = 1; }\n"
    "                break;\n"
    "            }\n"
    "            /* `yN` / `YN`.  The guard is `if (len)` -- NOT `nrep > 0`.  At\n"
    "             * nrep == 0 the arms are a no-op by arithmetic anyway, so the two\n"
    "             * spellings agree; kept as the oracle writes it so a future\n"
    "             * reader diffing the two files sees no difference at all. */\n"
    "            case RULE_OP_DUP_FIRST: {\n"
    "                int nrep = (int)prog[k++];\n"
    "                int c1 = u32_cl_start(buf, len, 1);   /* first cluster width */\n"
    "                if (len) { U32_ROOM(len + nrep * c1);\n"
    "                    for (i = len - 1; i >= 0; i--) buf[i + nrep * c1] = buf[i];\n"
    "                    for (i = 0; i < nrep; i++)\n"
    "                        for (j = 0; j < c1; j++) buf[i * c1 + j] = buf[nrep * c1 + j];\n"
    "                    len += nrep * c1; }\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_DUP_LAST: {\n"
    "                int nrep = (int)prog[k++];\n"
    "                int a = u32_cl_start(buf, len, u32_cl_count(buf, len) - 1);\n"
    "                int cw = len - a;\n"
    "                if (len) { U32_ROOM(len + nrep * cw);\n"
    "                    for (i = 0; i < nrep; i++)\n"
    "                        for (j = 0; j < cw; j++) buf[len + i * cw + j] = buf[a + j];\n"
    "                    len += nrep * cw; }\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_REPEAT: {\n"
    "                int nrep = (int)prog[k++];\n"
    "                if (nrep > 0) { U32_ROOM(len * (nrep + 1));\n"
    "                    for (j = 1; j <= nrep; j++)\n"
    "                        for (i = 0; i < len; i++) buf[j * len + i] = buf[i];\n"
    "                    len *= (nrep + 1); }\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_DUP_PREFIX: {\n"
    "                int nrep = (int)prog[k++];\n"
    "                int cpn = u32_cl_start(buf, len, nrep);\n"
    "                if (nrep > 0 && u32_cl_count(buf, len) >= nrep) {\n"
    "                    U32_ROOM(len + cpn);\n"
    "                    for (i = len - 1; i >= 0; i--) buf[i + cpn] = buf[i];\n"
    "                    for (i = 0; i < cpn; i++) buf[i] = buf[cpn + i];\n"
    "                    len += cpn; }\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_DUP_SUFFIX: {\n"
    "                int nrep = (int)prog[k++];\n"
    "                int nc = u32_cl_count(buf, len);\n"
    "                int cpn = len - u32_cl_start(buf, len, nc - nrep);\n"
    "                if (nrep > 0 && nc >= nrep) { U32_ROOM(len + cpn);\n"
    "                    for (i = 0; i < cpn; i++) buf[len + i] = buf[len - cpn + i];\n"
    "                    len += cpn; }\n"
    "                break;\n"
    "            }\n"
    "            /* Clamping derived from ruleproc.c, not inferred: when the start\n"
    "             * is past the end the word is left UNCHANGED -- not truncated and\n"
    "             * not emptied.  Guessing this produced a word-destroying\n"
    "             * difference on real rules. */\n"
    "            /* `xNM`.  The guard is `nc > N && (N+M) <= nc` and there is NO\n"
    "             * lower bound on M: `x20` on a word of 2+ clusters extracts ZERO\n"
    "             * clusters and EMPTIES the candidate.  A `if (m < 1) break;`\n"
    "             * looks like defensive hygiene and is a divergence -- game.rule\n"
    "             * uses x20/x30/x40/x50/x60/x70 heavily and every one of them\n"
    "             * differed. */\n"
    "            case RULE_OP_EXTRACT: {\n"
    "                int kk = (int)prog[k++], m = (int)prog[k++], x;\n"
    "                int nc = u32_cl_count(buf, len);\n"
    "                int a = u32_cl_start(buf, len, kk);\n"
    "                int b2 = u32_cl_start(buf, len, kk + m);\n"
    "                if (nc > kk && (kk + m) <= nc) {\n"
    "                    for (x = 0; x < b2 - a; x++) buf[x] = buf[a + x];\n"
    "                    len = x;\n"
    "                }\n"
    "                break;\n"
    "            }\n"
    "            /* `ONM`.  Same guard as extract -- the WHOLE range must fit, and\n"
    "             * the word is left untouched otherwise rather than omitting as\n"
    "             * much as it can.  The final length is where the shift loop\n"
    "             * STOPPED, which is NOT len - (b-a) at the boundary. */\n"
    "            case RULE_OP_OMIT: {\n"
    "                int kk = (int)prog[k++], m = (int)prog[k++], x;\n"
    "                int nc = u32_cl_count(buf, len);\n"
    "                int a = u32_cl_start(buf, len, kk);\n"
    "                int b2 = u32_cl_start(buf, len, kk + m);\n"
    "                if (nc > kk && (kk + m) <= nc) {\n"
    "                    for (x = a; x + (b2 - a) < len; x++) buf[x] = buf[x + (b2 - a)];\n"
    "                    len = x;\n"
    "                }\n"
    "                break;\n"
    "            }\n"
    "            /* `*N` insert every N CLUSTERS -- but applyrule32 divides by\n"
    "             * CODEPOINT count, so this arm is codepoint-based on purpose. */\n"
    "            case RULE_OP_DIV_INSERT: {\n"
    "                int x = (int)prog[k++]; uint c1 = prog[k++];\n"
    "                int total, w;\n"
    "                if (x <= 0) return U32_ERR_INVALID;\n"
    "                if (len < x) break;\n"
    "                total = len + len / x;\n"
    "                U32_ROOM(total);\n"
    "                w = total;\n"
    "                for (i = len - 1; i >= 0; i--) {\n"
    "                    if (((i + 1) % x) == 0) buf[--w] = c1;\n"
    "                    buf[--w] = buf[i];\n"
    "                }\n"
    "                len = total;\n"
    "                break;\n"
    "            }\n"
    "            /* `TNX` -- toggle the character after the Nth occurrence of X.\n"
    "             * N is ALREADY 0-BASED out of packrule32, so `30d` packs as\n"
    "             * (op, 0, 'd') and means \"after the FIRST d\".  An arm written as\n"
    "             * `seen++; if (seen == nth)` therefore never fires at all, and the\n"
    "             * separator must be skipped with `continue` so it cannot itself be\n"
    "             * the character toggled.  Both were wrong in a first draft and\n"
    "             * cost 13 divergences in 1,999,400 pairs -- the last 13. */\n"
    "            case RULE_OP_TOGGLE_SEP: {\n"
    "                int y = (int)prog[k++]; uint c1 = prog[k++];\n"
    "                int toggle_next = 0, occurrence = 0;\n"
    "                for (i = 0; i < len; i++) {\n"
    "                    if (buf[i] == c1) {\n"
    "                        if (occurrence == y) toggle_next = 1;\n"
    "                        else occurrence++;\n"
    "                        continue;\n"
    "                    }\n"
    "                    if (toggle_next) {\n"
    "                        uint u = u32_upper(buf[i], turkish, ct);\n"
    "                        buf[i] = (u != buf[i]) ? u : u32_lower(buf[i], turkish, ct);\n"
    "                        break;\n"
    "                    }\n"
    "                }\n"
    "                break;\n"
    "            }\n"
    "            /* `H` / `h`: replace the candidate with the hex of its UTF-8\n"
    "             * ENCODING.  Encoding first is the only reading that agrees with\n"
    "             * the byte engine on ASCII and is meaningful above it: hexing the\n"
    "             * codepoint values would give a different string for the same\n"
    "             * word depending on the engine. */\n"
    "            case RULE_OP_HEX_LOWER:\n"
    "            case RULE_OP_HEX_UPPER: {\n"
    "                uchar tmp[U32_EXPAND_MAX * 4];\n"
    "                int d = 0, nb;\n"
    "                /* Encode in place into a rolling scratch, two hex digits per\n"
    "                 * byte, working BACKWARDS so the growth is safe. */\n"
    "                nb = 0;\n"
    "                for (i = 0; i < len; i++) {\n"
    "                    uint cp = buf[i];\n"
    "                    if (!U32_ENCODABLE(cp)) continue;\n"
    "                    nb += (cp < 0x80u) ? 1 : (cp < 0x800u) ? 2\n"
    "                        : (cp < 0x10000u) ? 3 : 4;\n"
    "                }\n"
    "                U32_ROOM(nb * 2);\n"
    "                /* Second pass: write hex digits forwards while reading the\n"
    "                 * codepoints forwards.  Safe because 2 digits per byte is at\n"
    "                 * least 2 output slots per input slot. */\n"
    "                d = nb * 2;\n"
    "                for (i = len - 1; i >= 0; i--) {\n"
    "                    uint cp = buf[i];\n"
    "                    int m, c;\n"
    "                    if (!U32_ENCODABLE(cp)) continue;\n"
    "                    if (cp < 0x80u) { tmp[0] = (uchar)cp; c = 1; }\n"
    "                    else if (cp < 0x800u) { tmp[0] = (uchar)(0xC0u | (cp >> 6));\n"
    "                        tmp[1] = (uchar)(0x80u | (cp & 0x3Fu)); c = 2; }\n"
    "                    else if (cp < 0x10000u) { tmp[0] = (uchar)(0xE0u | (cp >> 12));\n"
    "                        tmp[1] = (uchar)(0x80u | ((cp >> 6) & 0x3Fu));\n"
    "                        tmp[2] = (uchar)(0x80u | (cp & 0x3Fu)); c = 3; }\n"
    "                    else { tmp[0] = (uchar)(0xF0u | (cp >> 18));\n"
    "                        tmp[1] = (uchar)(0x80u | ((cp >> 12) & 0x3Fu));\n"
    "                        tmp[2] = (uchar)(0x80u | ((cp >> 6) & 0x3Fu));\n"
    "                        tmp[3] = (uchar)(0x80u | (cp & 0x3Fu)); c = 4; }\n"
    "                    for (m = c - 1; m >= 0; m--) {\n"
    "                        uint hi = (uint)(tmp[m] >> 4), lo2 = (uint)(tmp[m] & 0xf);\n"
    "                        uint base = (op == RULE_OP_HEX_UPPER) ? 'A' : 'a';\n"
    "                        buf[--d] = (lo2 < 10u) ? ('0' + lo2) : (base + lo2 - 10u);\n"
    "                        buf[--d] = (hi  < 10u) ? ('0' + hi)  : (base + hi  - 10u);\n"
    "                    }\n"
    "                }\n"
    "                len = nb * 2;\n"
    "                break;\n"
    "            }\n"
    "\n"
    "            /* ---- character classes ---------------------------------- */\n"
    "            case RULE_OP_SUB_CLASS: {\n"
    "                uchar cb = (uchar)prog[k++]; uint y = prog[k++];\n"
    "                for (j = 0; j < len; j++)\n"
    "                    if (u32_class_match(cb, buf[j])) buf[j] = y;\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_PURGE_CLASS: {\n"
    "                uchar cb = (uchar)prog[k++]; int d = 0;\n"
    "                for (j = 0; j < len; j++)\n"
    "                    if (!u32_class_match(cb, buf[j])) buf[d++] = buf[j];\n"
    "                len = d; break;\n"
    "            }\n"
    "            case RULE_OP_TITLE_CLASS: {\n"
    "                uchar cb = (uchar)prog[k++]; int z = 0;\n"
    "                for (j = 0; j < len; j++) {\n"
    "                    uint ch = buf[j];\n"
    "                    if (u32_class_match(cb, ch)) { z = 0; continue; }\n"
    "                    if (u32_lower(ch, turkish, ct) != ch) { z = 1; continue; }\n"
    "                    if (!z) { buf[j] = u32_upper(ch, turkish, ct); z = 1; }\n"
    "                    else buf[j] = u32_lower(ch, turkish, ct);\n"
    "                }\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_TITLE_CLASS_HC: {\n"
    "                uchar cb = (uchar)prog[k++]; int z = 1;\n"
    "                for (j = 0; j < len; j++) {\n"
    "                    uint ch = buf[j];\n"
    "                    if (z) buf[j] = u32_upper(ch, turkish, ct);\n"
    "                    else   buf[j] = u32_lower(ch, turkish, ct);\n"
    "                    z = u32_class_match(cb, ch) ? 1 : 0;\n"
    "                }\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_REJ_HAS_CLASS: {\n"
    "                uchar cb = (uchar)prog[k++];\n"
    "                for (j = 0; j < len; j++)\n"
    "                    if (u32_class_match(cb, buf[j])) return U32_REJECTED;\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_REJ_NHAS_CLASS: {\n"
    "                uchar cb = (uchar)prog[k++];\n"
    "                for (j = 0; j < len; j++) if (u32_class_match(cb, buf[j])) break;\n"
    "                if (j >= len) return U32_REJECTED; break;\n"
    "            }\n"
    "            case RULE_OP_REJ_FIRST_CLASS: {\n"
    "                uchar cb = (uchar)prog[k++];\n"
    "                if (len > 0 && !u32_class_match(cb, buf[0])) return U32_REJECTED;\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_REJ_LAST_CLASS: {\n"
    "                uchar cb = (uchar)prog[k++];\n"
    "                if (len > 0) { int a = u32_cl_start(buf, len, u32_cl_count(buf, len) - 1);\n"
    "                    if (!u32_class_match(cb, buf[a])) return U32_REJECTED; }\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_REJ_AT_CLASS: {\n"
    "                int y = (int)prog[k++]; uchar cb = (uchar)prog[k++];\n"
    "                if (y >= u32_cl_count(buf, len)) return U32_REJECTED;\n"
    "                if (!u32_class_match(cb, buf[u32_cl_start(buf, len, y)]))\n"
    "                    return U32_REJECTED;\n"
    "                break;\n"
    "            }\n"
    "            case RULE_OP_REJ_CNT_CLASS: {\n"
    "                int y = (int)prog[k++]; uchar cb = (uchar)prog[k++];\n"
    "                int cnt = 0;\n"
    "                for (j = 0; j < len; j++) if (u32_class_match(cb, buf[j])) cnt++;\n"
    "                if (cnt < y) return U32_REJECTED; break;\n"
    "            }\n"
    "\n"
    "            /* An opcode this walker does not implement -- the string-operand\n"
    "             * family, 0x1002..0x100C.  A rule containing one must never have\n"
    "             * been routed here: it is marked \"no UTF-32 form\" host-side and\n"
    "             * walked on the CPU.  Reaching this is a WIRING bug, not a data\n"
    "             * condition, so it fails the pair loudly rather than emitting a\n"
    "             * half-applied candidate. */\n"
    "            default:\n"
    "                return U32_ERR_INVALID;\n"
    "        }\n"
    "    }\n"
    "    return len;\n"
    "}\n"
    "\n"
    "U32_SI int u32_run_pair(\n"
    "    U32_GLOBAL const uchar *words, uint wpos, int wlen,\n"
    "    U32_GLOBAL const uchar *rule_program,\n"
    "    uint byte_roff, uint u32_roff,\n"
    "    uint wclass,\n"
    "    U32_BUF uchar *bytebuf,                  /* RULE_BUF_MAX uchars  */\n"
    "    U32_BUF uint *u32buf, U32_BUF uint *u32mem,     /* U32_BUF_ELEMS uints each */\n"
    "    U32_BUF uchar *out, int outmax,\n"
    "    U32_GLOBAL const uint *case_tab,\n"
    "    U32_SCRATCH int *engine_out)\n"
    "{\n"
    "    int u32_can  = (u32_roff & U32_R_HASFORM) != 0u;\n"
    "    int byte_can = (u32_roff & U32_R_BYTEOK)  != 0u;\n"
    "    int eng = u32_pick_engine(wclass, u32_can, byte_can);\n"
    "    int n;\n"
    "\n"
    "    *engine_out = eng;\n"
    "    if (eng < 0) return -1;\n"
    "\n"
    "    if (eng == 0) {\n"
    "        /* ---- byte engine: unchanged semantics, unchanged walker ---- */\n"
    "        for (int i = 0; i < wlen; i++) bytebuf[i] = words[wpos + i];\n"
    "        n = apply_rule(rule_program + byte_roff, bytebuf, wlen);\n"
    "        if (n < 0) return -1;\n"
    "        for (int i = 0; i < n && i < outmax; i++) out[i] = bytebuf[i];\n"
    "        return (n > outmax) ? outmax : n;\n"
    "    }\n"
    "\n"
    "    /* ---- UTF-32 engine ---------------------------------------------\n"
    "     * Decode, walk, encode.  The decode is STRICT and its failure is a\n"
    "     * property of the data: a class-A or class-W word decodes by\n"
    "     * construction, so a failure here means the host class was wrong, and\n"
    "     * skipping the pair is what the CPU does too (applyrule_u32 returns -3\n"
    "     * and every caller skips a negative). */\n"
    "    n = u32_decode(words + wpos, wlen, u32buf, U32_BUF_ELEMS);\n"
    "    if (n < 0) return (n == U32_ERR_NOROOM) ? -2 : -1;\n"
    "\n"
    "    n = apply_rule32((U32_GLOBAL const uint *)(rule_program + (u32_roff & U32_R_OFFMASK)),\n"
    "                     u32buf, u32mem, n, case_tab);\n"
    "    if (n == U32_ERR_NOROOM) return -2;\n"
    "    if (n < 0) return -1;\n"
    "\n"
    "    n = u32_encode(u32buf, n, out, outmax);\n"
    "    if (n < 0) return -2;\n"
    "    return n;\n"
    "}\n"
;
